<script setup lang="ts">import type{RangeControl}from'../../types/protocol';const p=defineProps<{control:RangeControl}>();const emit=defineEmits<{change:[number]}>();let last=0;function mapped(e:Event){const raw=Number((e.target as HTMLInputElement).value);return p.control.scale==='log'?Math.exp(Math.log(p.control.min)+(Math.log(p.control.max)-Math.log(p.control.min))*raw):p.control.min+(p.control.max-p.control.min)*raw}function input(e:Event){const now=performance.now();if(now-last>33){last=now;emit('change',mapped(e))}}function final(e:Event){emit('change',mapped(e))}function normalized(){return p.control.scale==='log'?(Math.log(p.control.value)-Math.log(p.control.min))/(Math.log(p.control.max)-Math.log(p.control.min)):(p.control.value-p.control.min)/(p.control.max-p.control.min)}</script>
<template><div class="fader"><label>{{control.label}}</label><input aria-orientation="vertical" type="range" min="0" max="1" step="0.001" :value="normalized()" :disabled="control.read_only" @input="input" @change="final"><output>{{control.value.toFixed(2)}} {{control.unit}}</output></div></template>
